185	@@ -0,0 +1,12 @@
186	+/* ============================ Đi dạo: cần gạt ảo (thuần) ============================
187	+   Độ lệch núm so với tâm (px, phải +, xuống +) → hướng đi (mz: lên màn hình là tới, mx: phải) độ dài 1 và cờ chạy.
188	+   Gạt nhẹ (k < run) là đi, gạt hết cỡ (k ≥ run) là chạy; k < dead là vùng chết. Không cấp phát (gọi mỗi khung). */
189	+import { CONFIG } from '../../config';
190	+
191	+export function stStick(dx: number, dy: number, radius: number, out: { mx: number; mz: number; run: boolean }): void {
192	+  const S = CONFIG.stroll.stick;
193	+  const h = Math.sqrt(dx * dx + dy * dy);
194	+  const k = radius > 0 ? Math.min(1, h / radius) : 0;
195	+  if (k < S.dead || h < 1e-9) { out.mx = 0; out.mz = 0; out.run = false; return; }
196	+  out.mx = dx / h; out.mz = -dy / h; out.run = k >= S.run;
197	+}
198	diff --git a/src/explore/stroll/touch.ts b/src/explore/stroll/touch.ts
199	new file mode 100644
200	index 0000000..414bd29
201	--- /dev/null
202	+++ b/src/explore/stroll/touch.ts
203	@@ -0,0 +1,87 @@
204	+/* ============================ Đi dạo: điều khiển cảm ứng ============================
205	+   Ba con trỏ độc lập trên #stHud: cần gạt #stPad (ngón trái), vuốt #stLook (nửa phải, dưới các nút), nút #stJump; #stPhoto là nút bấm thường (cả máy tính).
206	+   - Mỗi vùng chỉ theo con trỏ đã chạm vào nó (pointerId riêng + setPointerCapture), nên giữ cần gạt, vuốt camera và chạm Nhảy cùng lúc không lẫn nhau.
207	+   - Nhảy theo cạnh: một lần chạm gọi jump() một lần (stStep nhảy lại ngay khi chạm đất nếu jump còn giữ).
208	+   - Thả tay, pointercancel, lostpointercapture, blur, ẩn tab, xoay màn hình, đổi cỡ khung nhìn: reset() — cần gạt về giữa, nhân vật dừng (Review Focus 2).
209	+   - read(out) chỉ ghi đè mx / mz / run khi cần gạt đang được giữ (cảm ứng ưu tiên phím); mỗi khung không cấp phát (D-018). */
210	+import { CONFIG } from '../../config';
211	+import { stStick } from './stick';
212	+import type { StInput } from './motion';
213	+
214	+export interface StTouchHandlers { look(dxPx: number, dyPx: number): void; jump(): void; photo(): void; activity(): void }
215	+
216	+export function stTouchBind(root: HTMLElement, h: StTouchHandlers): { read(out: StInput): void; reset(): void } {
217	+  const pad = root.querySelector<HTMLElement>('#stPad'), knob = root.querySelector<HTMLElement>('#stKnob');
218	+  const look = root.querySelector<HTMLElement>('#stLook'), jump = root.querySelector<HTMLElement>('#stJump'), photo = root.querySelector<HTMLElement>('#stPhoto');
219	+  const size = CONFIG.stroll.stick.size;
220	+  root.style.setProperty('--st-pad', size + 'px');   // đường kính cần gạt lấy từ CONFIG
221	+  let padId = -1, cx = 0, cy = 0, dx = 0, dy = 0, r = size / 2;   // cần gạt: con trỏ, tâm (px màn hình, chốt lúc chạm), độ lệch núm
222	+  let lookId = -1, lx = 0, ly = 0;                                 // vuốt camera: con trỏ, vị trí trước
223	+  let jumpId = -1;
224	+  const own = (el: HTMLElement, e: PointerEvent) => { try { el.setPointerCapture(e.pointerId); } catch { /* con trỏ không còn hoạt động (sự kiện giả) */ } };
225	+
226	+  const knobTo = (x: number, y: number) => { if (knob) knob.style.transform = x === 0 && y === 0 ? '' : `translate(${x}px,${y}px)`; };
227	+  const reset = () => { padId = -1; lookId = -1; jumpId = -1; dx = 0; dy = 0; knobTo(0, 0); };
228	+
229	+  if (pad) {
230	+    pad.addEventListener('pointerdown', (e) => {
231	+      if (padId >= 0) return;
232	+      e.preventDefault();
233	+      const b = pad.getBoundingClientRect();
234	+      cx = b.left + b.width / 2; cy = b.top + b.height / 2; r = b.width / 2 || size / 2;
235	+      padId = e.pointerId; own(pad, e); h.activity();
236	+      pad.dispatchEvent(new PointerEvent('pointermove', { pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY }));   // núm theo ngón ngay lúc chạm
237	+    });
238	+    pad.addEventListener('pointermove', (e) => {
239	+      if (e.pointerId !== padId) return;
240	+      dx = e.clientX - cx; dy = e.clientY - cy;
241	+      const d = Math.sqrt(dx * dx + dy * dy);
242	+      if (d > r) { dx = dx / d * r; dy = dy / d * r; }   // núm không ra khỏi vòng
243	+      knobTo(dx, dy); h.activity();
244	+    });
245	+    const padEnd = (e: PointerEvent) => { if (e.pointerId === padId) { padId = -1; dx = 0; dy = 0; knobTo(0, 0); } };
246	+    pad.addEventListener('pointerup', padEnd);
247	+    pad.addEventListener('pointercancel', padEnd);
248	+    pad.addEventListener('lostpointercapture', padEnd);
249	+  }
250	+
251	+  if (look) {
252	+    look.addEventListener('pointerdown', (e) => {
253	+      if (lookId >= 0) return;
254	+      e.preventDefault();
255	+      lookId = e.pointerId; lx = e.clientX; ly = e.clientY; own(look, e); h.activity();
256	+    });
257	+    look.addEventListener('pointermove', (e) => {
258	+      if (e.pointerId !== lookId) return;
259	+      h.look(e.clientX - lx, e.clientY - ly); h.activity();
260	+      lx = e.clientX; ly = e.clientY;
261	+    });
262	+    const lookEnd = (e: PointerEvent) => { if (e.pointerId === lookId) lookId = -1; };
263	+    look.addEventListener('pointerup', lookEnd);
264	+    look.addEventListener('pointercancel', lookEnd);
265	+    look.addEventListener('lostpointercapture', lookEnd);
266	+  }
267	+
268	+  if (jump) {
269	+    jump.addEventListener('pointerdown', (e) => {
270	+      e.preventDefault();
271	+      if (jumpId < 0) { jumpId = e.pointerId; own(jump, e); h.jump(); h.activity(); }   // một lần chạm một lần nhảy
272	+    });
273	+    const jumpEnd = (e: PointerEvent) => { if (e.pointerId === jumpId) jumpId = -1; };
274	+    jump.addEventListener('pointerup', jumpEnd);
275	+    jump.addEventListener('pointercancel', jumpEnd);
276	+    jump.addEventListener('lostpointercapture', jumpEnd);
277	+  }
278	+
279	+  if (photo) photo.addEventListener('click', () => { h.activity(); h.photo(); });   // chuột và chạm đều ra click
280	+
281	+  window.addEventListener('blur', reset);
282	+  document.addEventListener('visibilitychange', () => { if (document.hidden) reset(); });
283	+  window.addEventListener('orientationchange', reset);
284	+  window.addEventListener('resize', reset);
285	+
286	+  return {
287	+    read(out: StInput): void { if (padId >= 0) stStick(dx, dy, r, out); },
288	+    reset
289	+  };
290	+}
